using System;using System.IO;using System.Runtime.InteropServices;using System.Collections.Generic;using System.Drawing.Text;using System.Linq;using Microsoft.Win32;using System.Web.Script.Serialization;
static class ModernFolder {
 [ComImport,Guid("DC1C5A9C-E88A-4DDE-A5A1-60F82A20AEF7")]class OpenDialog{}
 [ComImport,Guid("D57C7288-D4AD-4768-BE02-9D969532D960"),InterfaceType(ComInterfaceType.InterfaceIsIUnknown)]interface Dialog{
 [PreserveSig]int Show(IntPtr parent);void SetFileTypes(uint n,IntPtr types);void SetFileTypeIndex(uint i);void GetFileTypeIndex(out uint i);void Advise(IntPtr sink,out uint cookie);void Unadvise(uint cookie);void SetOptions(uint options);void GetOptions(out uint options);void SetDefaultFolder(IntPtr item);void SetFolder(IntPtr item);void GetFolder(out IntPtr item);void GetCurrentSelection(out IntPtr item);void SetFileName([MarshalAs(UnmanagedType.LPWStr)]string name);void GetFileName(out IntPtr name);void SetTitle([MarshalAs(UnmanagedType.LPWStr)]string title);void SetOkButtonLabel([MarshalAs(UnmanagedType.LPWStr)]string label);void SetFileNameLabel([MarshalAs(UnmanagedType.LPWStr)]string label);void GetResult(out ShellItem item);void AddPlace(IntPtr item,int where);void SetDefaultExtension([MarshalAs(UnmanagedType.LPWStr)]string ext);void Close(int hr);void SetClientGuid(ref Guid guid);void ClearClientData();void SetFilter(IntPtr filter);void GetResults(out IntPtr items);void GetSelectedItems(out IntPtr items);}
 [ComImport,Guid("43826D1E-E718-42EE-BC55-A1E261C37BFE"),InterfaceType(ComInterfaceType.InterfaceIsIUnknown)]interface ShellItem{void BindToHandler(IntPtr bind,ref Guid handler,ref Guid iid,out IntPtr result);void GetParent(out ShellItem parent);void GetDisplayName(uint kind,out IntPtr name);void GetAttributes(uint mask,out uint attributes);void Compare(ShellItem other,uint hint,out int order);}
 internal static string Pick(IntPtr parent,string title){var d=(Dialog)new OpenDialog();ShellItem item=null;IntPtr name=IntPtr.Zero;try{uint opts;d.GetOptions(out opts);d.SetOptions(opts|0x20|0x40|0x800|0x02000000);d.SetTitle(title);d.SetOkButtonLabel("Choose folder");int hr=d.Show(parent);if(hr==unchecked((int)0x800704c7))return null;if(hr<0)Marshal.ThrowExceptionForHR(hr);d.GetResult(out item);item.GetDisplayName(0x80058000,out name);return Marshal.PtrToStringUni(name);}finally{if(name!=IntPtr.Zero)Marshal.FreeCoTaskMem(name);if(item!=null)Marshal.ReleaseComObject(item);Marshal.ReleaseComObject(d);}}
}
static class FontOperations {
 [DllImport("gdi32.dll",CharSet=CharSet.Unicode)]static extern int AddFontResourceEx(string file,uint flags,IntPtr reserved);
 [DllImport("gdi32.dll",CharSet=CharSet.Unicode)]static extern bool RemoveFontResourceEx(string file,uint flags,IntPtr reserved);
 [DllImport("user32.dll",CharSet=CharSet.Unicode)]static extern IntPtr SendMessageTimeout(IntPtr h,uint msg,IntPtr w,IntPtr l,uint flags,uint ms,out IntPtr result);
 static string Folder{get{return Program.Test!=null?Path.Combine(Program.Test,"InstalledFonts"):Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),@"Microsoft\Windows\Fonts");}}
 static string Records{get{return Path.Combine(Program.Root,"Jago-font-installs.json");}}
 static Dictionary<string,string> Read(){try{return new JavaScriptSerializer().Deserialize<Dictionary<string,string>>(File.ReadAllText(Records));}catch{return new Dictionary<string,string>();}}
 static void Save(Dictionary<string,string> data){Directory.CreateDirectory(Program.Root);File.WriteAllText(Records,new JavaScriptSerializer().Serialize(data));}
 static void Notify(){IntPtr r;SendMessageTimeout(new IntPtr(0xffff),0x1d,IntPtr.Zero,IntPtr.Zero,2,1000,out r);}
 internal static Dictionary<string,string> UserFonts(){var data=Read();if(Program.Test==null)using(var key=Registry.CurrentUser.OpenSubKey(@"SOFTWARE\Microsoft\Windows NT\CurrentVersion\Fonts")){if(key!=null)foreach(string name in key.GetValueNames()){string value=Convert.ToString(key.GetValue(name));if(String.IsNullOrWhiteSpace(value))continue;try{string full=Path.GetFullPath(Path.IsPathRooted(value)?value:Path.Combine(Folder,value));if(full.StartsWith(Path.GetFullPath(Folder)+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase)&&new[]{".ttf",".otf"}.Contains(Path.GetExtension(full).ToLowerInvariant()))data[name]=full;}catch{}}}return data;}
 internal static object List(){var owned=Read();return UserFonts().OrderBy(p=>p.Key).Select(p=>new{name=p.Key,file=Path.GetFileName(p.Value),origin=owned.ContainsKey(p.Key)?"Installed through Jago":"User-installed",missing=!File.Exists(p.Value)}).ToArray();}
 internal static object Backups(){string folder=Path.Combine(Program.Root,"Font-backups");return Directory.Exists(folder)?Directory.GetFiles(folder).Where(f=>new[]{".ttf",".otf"}.Contains(Path.GetExtension(f).ToLowerInvariant())).Select(f=>new{name=Path.GetFileName(f)}).ToArray():new object[0];}
 internal static string Restore(string name){if(name!=Path.GetFileName(name)||String.IsNullOrWhiteSpace(name))throw new InvalidDataException("Choose a font backup from the list.");return Install(Path.Combine(Program.Root,"Font-backups",name));}
 internal static string Install(string source){if(!new[]{".ttf",".otf"}.Contains(Path.GetExtension(source).ToLowerInvariant())||new FileInfo(source).Length>20000000)throw new InvalidOperationException("Choose a TrueType or OpenType font file under 20 MB.");string family;using(var p=new PrivateFontCollection()){p.AddFontFile(source);if(p.Families.Length==0)throw new InvalidDataException("This font cannot be read.");family=p.Families[0].Name;}Directory.CreateDirectory(Folder);string hash;using(var sha=System.Security.Cryptography.SHA256.Create())using(var stream=File.OpenRead(source))hash=BitConverter.ToString(sha.ComputeHash(stream)).Replace("-","").Substring(0,12);string target=Path.Combine(Folder,"Jago-"+hash+"-"+Path.GetFileName(source));if(!File.Exists(target))File.Copy(source,target,false);string key=family+" (Jago "+hash+")";if(Program.Test==null){if(AddFontResourceEx(target,0,IntPtr.Zero)==0)throw new InvalidOperationException("Windows could not register this font.");using(var registry=Registry.CurrentUser.CreateSubKey(@"SOFTWARE\Microsoft\Windows NT\CurrentVersion\Fonts"))registry.SetValue(key,target,RegistryValueKind.String);Notify();}var records=Read();records[key]=target;Save(records);return family;}
 internal static void Uninstall(string key){var all=UserFonts();string target;if(!all.TryGetValue(key,out target))throw new InvalidOperationException("Choose a registered user font. Machine fonts use Windows settings.");string full=Path.GetFullPath(target),root=Path.GetFullPath(Folder).TrimEnd(Path.DirectorySeparatorChar);if(!full.StartsWith(root+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase))throw new InvalidDataException("Font is outside your user font folder.");if((File.GetAttributes(full)&FileAttributes.ReparsePoint)!=0)throw new InvalidDataException("Linked font files use Windows settings.");string backup=Path.Combine(Program.Root,"Font-backups",Path.GetFileName(full));Directory.CreateDirectory(Path.GetDirectoryName(backup));File.Copy(full,backup,true);if(Program.Test==null){using(var registry=Registry.CurrentUser.OpenSubKey(@"SOFTWARE\Microsoft\Windows NT\CurrentVersion\Fonts",true)){string value=registry==null?null:Convert.ToString(registry.GetValue(key));string registered=String.IsNullOrEmpty(value)?null:Path.GetFullPath(Path.IsPathRooted(value)?value:Path.Combine(Folder,value));if(!String.Equals(registered,full,StringComparison.OrdinalIgnoreCase))throw new InvalidOperationException("Registration changed. Refresh the font list before trying again.");registry.DeleteValue(key,false);}RemoveFontResourceEx(full,0,IntPtr.Zero);Notify();}var records=Read();records.Remove(key);Save(records);}
}
sealed partial class WorldWindow {
 void RegisterPDFDefault(){if(Program.Test!=null)return;string name="Jago.LibraryProduction.PDF",exe=System.Reflection.Assembly.GetExecutingAssembly().Location;using(var key=Registry.CurrentUser.CreateSubKey(@"Software\Classes\"+name)){key.SetValue("","Jago PDF document");using(var command=key.CreateSubKey(@"shell\open\command"))command.SetValue("", "\""+exe+"\" \"%1\"");}using(var key=Registry.CurrentUser.CreateSubKey(@"Software\Classes\.pdf\OpenWithProgids"))key.SetValue(name,"",RegistryValueKind.String);using(var key=Registry.CurrentUser.CreateSubKey(@"Software\Jago\LibraryProduction\Capabilities")){key.SetValue("ApplicationName","Jago Library + Production Studio");key.SetValue("ApplicationDescription","Offline PDF, asset library and creative production tools");using(var formats=key.CreateSubKey("FileAssociations"))formats.SetValue(".pdf",name);}using(var key=Registry.CurrentUser.CreateSubKey(@"Software\RegisteredApplications"))key.SetValue("Jago Library + Production Studio",@"Software\Jago\LibraryProduction\Capabilities");System.Diagnostics.Process.Start(new System.Diagnostics.ProcessStartInfo("ms-settings:defaultapps"){UseShellExecute=true});}
 internal async System.Threading.Tasks.Task OpenPDFDocument(string file){string full=Path.GetDirectoryName(file),id;using(var sha=System.Security.Cryptography.SHA256.Create())id="r"+BitConverter.ToString(sha.ComputeHash(System.Text.Encoding.UTF8.GetBytes(full.ToLowerInvariant()))).Replace("-","").Substring(0,12).ToLowerInvariant();browser.CoreWebView2.SetVirtualHostNameToFolderMapping(id+".jagolibrary.example",full,Microsoft.Web.WebView2.Core.CoreWebView2HostResourceAccessKind.Allow);string key=id+":"+Path.GetFileName(file);assetPaths[key]=file;var data=new System.Web.Script.Serialization.JavaScriptSerializer().Serialize(new{id=key,name=Path.GetFileName(file),type="pdf",size=new FileInfo(file).Length,rootId=id,rootPath=full,url="https://"+id+".jagolibrary.example/"+Uri.EscapeDataString(Path.GetFileName(file))});await browser.CoreWebView2.ExecuteScriptAsync("(()=>{const a="+data+";if(!state.roots.some(r=>r.id===a.rootId))state.roots.push({id:a.rootId,path:a.rootPath,name:a.rootPath});addAsset(a);mark();selected.clear();selected.add(a.id);focus=a.id;setWorkspace('library');renderLibrary();renderDetails();openPDFReader(a)})()");}
 void HandleFontOperation(Dictionary<string,object> m){string type=Convert.ToString(m["type"]);if(type=="font-publish"){string file;if(!assetPaths.TryGetValue(Convert.ToString(m["id"]),out file))throw new InvalidOperationException("Re-add the original font file.");JagoFontPool.Publish(file,Convert.ToString(m["family"]),Convert.ToString(m["licence"]));ManagedPost(new{type="font-published",message="Font copied to the shared Jago pool. Other studios can refresh their font pool."});return;}if(type=="pdf-default"){RegisterPDFDefault();return;}if(type=="font-install"){string source;if(!assetPaths.TryGetValue(Convert.ToString(m["id"]),out source))throw new InvalidOperationException("Re-add the original font file before installing it.");string name=FontOperations.Install(source);ManagedPost(new{type="font-operation",message=name+" installed for your Windows user. No admin access required.",installed=FontOperations.List(),backups=FontOperations.Backups()});}else if(type=="font-uninstall"){FontOperations.Uninstall(Convert.ToString(m["name"]));ManagedPost(new{type="font-operation",message="Font uninstalled. A backup remains in Jago's local data.",installed=FontOperations.List(),backups=FontOperations.Backups()});}else if(type=="font-restore"){string name=FontOperations.Restore(Convert.ToString(m["name"]));ManagedPost(new{type="font-operation",message=name+" restored for your Windows user.",installed=FontOperations.List(),backups=FontOperations.Backups()});}else if(type=="font-manager")ManagedPost(new{type="font-operation",installed=FontOperations.List(),backups=FontOperations.Backups()});else if(type=="windows-fonts")System.Diagnostics.Process.Start(new System.Diagnostics.ProcessStartInfo("ms-settings:fonts"){UseShellExecute=true});}
}
